:root {
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: #111827;
  background: #ffffff;
  line-height: 1.5;
}

a {
  color: #1d4ed8;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font: inherit;
  cursor: pointer;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1rem 2rem;
  border-bottom: 1px solid #e5e7eb;
}

.logo {
  font-weight: 800;
  font-size: 1.4rem;
  color: #111827;
  text-decoration: none;
  letter-spacing: 0.02em;
}

.main-nav {
  display: flex;
  gap: 1.25rem;
  flex: 1;
}

.main-nav a,
.cart-link {
  color: #111827;
  text-decoration: none;
  font-weight: 600;
}

.main-nav a:hover,
.cart-link:hover {
  text-decoration: underline;
}

/* Breadcrumb */
.breadcrumb ol {
  list-style: none;
  display: flex;
  gap: 0.5rem;
  padding: 0;
  margin: 0 0 1.5rem;
  font-size: 0.9rem;
  color: #4b5563;
}

.breadcrumb li + li::before {
  content: '/';
  margin-right: 0.5rem;
  color: #4b5563;
}

/* Product layout */
.product-layout {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  gap: 2.5rem;
  padding: 2rem;
  max-width: 1100px;
  margin: 0 auto;
  align-items: start;
}

.breadcrumb {
  grid-column: 1 / -1;
}

.gallery img {
  width: 100%;
  border-radius: 8px;
  background: #e5e7eb;
}

.gallery-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
  color: #111827;
}

.gallery-controls button {
  background: #f3f4f6;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  padding: 0.45rem 0.9rem;
  color: #111827;
}

.product-info h1 {
  margin: 0 0 0.5rem;
  font-size: 2rem;
}

.price {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.4rem;
  font-weight: 700;
  position: relative;
  margin: 0.5rem 0 1.25rem;
}

.info-button {
  border-radius: 50%;
  border: 1px solid #4b5563;
  background: #ffffff;
  color: #111827;
  width: 1.4rem;
  height: 1.4rem;
  font-size: 0.85rem;
  line-height: 1;
  padding: 0;
}

.tooltip {
  position: absolute;
  top: 100%;
  left: 0;
  background: #111827;
  color: #ffffff;
  padding: 0.4rem 0.6rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-weight: 400;
  white-space: nowrap;
  z-index: 10;
}

/* Options */
.option-block {
  margin-bottom: 1.25rem;
}

.swatches {
  display: flex;
  gap: 0.25rem;
}

.swatch {
  appearance: none;
  -webkit-appearance: none;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 1px #4b5563;
  margin: 0;
  cursor: pointer;
}

.swatch:checked {
  box-shadow: 0 0 0 2px #111827;
}

.swatch:focus-visible {
  outline: 2px solid #1d4ed8;
  outline-offset: 2px;
}

.selection {
  margin: 0.5rem 0 0;
  color: #111827;
}

.size-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.size-row label {
  font-weight: 600;
}

.size-row button {
  background: none;
  border: none;
  padding: 0;
  color: #1d4ed8;
  text-decoration: underline;
}

select {
  font: inherit;
  padding: 0.5rem 0.75rem;
  border: 1px solid #4b5563;
  border-radius: 6px;
  color: #111827;
  background: #ffffff;
  min-width: 12rem;
}

.quantity {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.quantity button {
  width: 2.25rem;
  height: 2.25rem;
  border: 1px solid #4b5563;
  background: #ffffff;
  color: #111827;
  border-radius: 6px;
  font-size: 1.1rem;
  line-height: 1;
}

.quantity input {
  width: 4rem;
  text-align: center;
  font: inherit;
  padding: 0.45rem 0.25rem;
  border: 1px solid #4b5563;
  border-radius: 6px;
  color: #111827;
}

.buy-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 1.5rem 0 1rem;
}

.primary-button {
  background: #111827;
  color: #ffffff;
  border: none;
  padding: 0.8rem 1.6rem;
  border-radius: 6px;
  font-weight: 700;
  font-size: 1rem;
}

.wishlist-button {
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  border: 1px solid #4b5563;
  background: #ffffff;
  color: #b91c1c;
  font-size: 1.3rem;
  line-height: 1;
}

.wishlist-button[aria-pressed='true'] {
  background: #fef2f2;
}

.alert {
  background: #fef2f2;
  border: 1px solid #b91c1c;
  color: #b91c1c;
  padding: 0.6rem 0.8rem;
  border-radius: 6px;
}

.status {
  background: #f0fdf4;
  border: 1px solid #166534;
  color: #166534;
  padding: 0.6rem 0.8rem;
  border-radius: 6px;
}

/* More information tabs */
.more-info {
  max-width: 1100px;
  margin: 1rem auto 0;
  padding: 0 2rem;
}

.tablist {
  display: flex;
  gap: 0.25rem;
  border-bottom: 2px solid #e5e7eb;
}

.tab {
  background: #f3f4f6;
  color: #111827;
  border: none;
  padding: 0.7rem 1.4rem;
  border-radius: 6px 6px 0 0;
  font-weight: 600;
}

.tab[aria-selected='true'] {
  background: #111827;
  color: #ffffff;
}

.tabpanel {
  padding: 1.25rem 0.25rem;
}

/* FAQ */
.faq {
  max-width: 1100px;
  margin: 1rem auto 0;
  padding: 0 2rem;
}

.faq-item {
  border-bottom: 1px solid #e5e7eb;
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1rem 0;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  color: #111827;
}

.faq-answer {
  padding: 0 0 1rem;
  color: #374151;
}

.faq-answer p {
  margin: 0;
}

/* Footer */
.site-footer {
  background: #f3f4f6;
  padding: 2.5rem 2rem;
  margin-top: 3rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2rem;
}

.site-footer h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

/* Size guide dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(17, 24, 39, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.dialog {
  background: #ffffff;
  color: #111827;
  border-radius: 10px;
  padding: 1.5rem;
  max-width: 480px;
  width: 100%;
  max-height: 90vh;
  overflow: auto;
}

.dialog h2 {
  margin-top: 0;
}

.size-chart {
  border-collapse: collapse;
  width: 100%;
  margin: 1rem 0;
}

.size-chart caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.size-chart th,
.size-chart td {
  border: 1px solid #d1d5db;
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.field {
  display: grid;
  gap: 0.35rem;
  margin: 0 0 1rem;
}

.field label {
  font-weight: 600;
}

.field input {
  font: inherit;
  padding: 0.5rem 0.75rem;
  border: 1px solid #4b5563;
  border-radius: 6px;
  color: #111827;
}

.unit-picker {
  display: flex;
  gap: 1.25rem;
  margin-bottom: 1rem;
}

.unit-picker label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.recommendation {
  background: #f0fdf4;
  border: 1px solid #166534;
  color: #166534;
  padding: 0.6rem 0.8rem;
  border-radius: 6px;
}

@media (max-width: 800px) {
  .product-layout {
    grid-template-columns: 1fr;
  }

  .site-footer {
    grid-template-columns: 1fr;
  }
}

